def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where((bins < item) | (bins <= 0), -np.inf, np.where(remaining < 0.1 * bins, -np.inf, remaining))

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, remaining, -np.inf)
